import{_ as t,o,c as s,a3 as a}from"./chunks/framework.BTQ4eCVb.js";const g=JSON.parse('{"title":"Expenses — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Expenses — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/expenses"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Expenses — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/expenses"}]]},"headers":[],"relativePath":"user-guide/expenses.md","filePath":"user-guide/expenses.md","lastUpdated":1788286482000}'),r={name:"user-guide/expenses.md"};function n(i,e,d,c,l,p){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="expenses-—-user-guide" tabindex="-1">Expenses — User Guide <a class="header-anchor" href="#expenses-—-user-guide" aria-label="Permalink to &quot;Expenses — User Guide&quot;">​</a></h1><h2 id="who-can-use-expenses" tabindex="-1">Who can use Expenses <a class="header-anchor" href="#who-can-use-expenses" aria-label="Permalink to &quot;Who can use Expenses&quot;">​</a></h2><p>Enable the <strong>Expenses</strong> module from Marketplace (free) — no other modules are required first. Your role must include the relevant permissions (<code>view</code>, <code>create</code>, <code>update</code>, <code>delete</code>, <code>restore</code>, <code>force.delete</code>, <code>assign</code>, <code>submit</code>, <code>approve</code>, <code>reject</code>, <code>pay</code>, <code>cancel</code> as needed).</p><p>Without <strong>assign</strong>, you only see expenses assigned to you.</p><h2 id="list-table" tabindex="-1">List &amp; table <a class="header-anchor" href="#list-table" aria-label="Permalink to &quot;List &amp; table&quot;">​</a></h2><p>Open <strong>Expenses</strong> from the sidebar, under the <strong>Purchasing</strong> group (after Purchase Orders). Search by title or number, filter by status or category, toggle <strong>My Expenses</strong>, and switch KPI cards (Total, Mine, Draft, Submitted, Approved, Paid) to quick-filter the table. The table shows category, status, amount, expense date, assignee, and the <strong>latest note</strong>.</p><p>Use <strong>Manage categories</strong> (visible with <code>expenses.create</code>, <code>expenses.update</code>, or <code>expenses.delete</code>) to add, rename, activate/deactivate, or delete workspace expense categories. New workspaces start with Travel, Office, Software, Utilities, and Other. You cannot delete <strong>Other</strong> (it is the default for new expenses and Purchase Order convert). You also cannot delete a category that still has expenses. Renaming a starter category keeps its slug.</p><ul><li>Users with <strong>restore</strong> can filter <strong>Active / Include deleted / Deleted only</strong>, then <strong>Restore</strong> a soft-deleted expense from the row menu</li><li><strong>Delete permanently</strong> requires <code>expenses.force.delete</code> — granted to the workspace <strong>owner</strong> by default</li></ul><h2 id="create-an-expense" tabindex="-1">Create an expense <a class="header-anchor" href="#create-an-expense" aria-label="Permalink to &quot;Create an expense&quot;">​</a></h2><ol><li>Click <strong>New expense</strong></li><li>Enter a title, category (from your workspace list), amount, and optional tax amount</li><li>Optionally set currency and an expense date</li><li>If <strong>Vendors</strong> or <strong>Purchase Orders</strong> are installed on your workspace, optionally link a vendor and/or a purchase order</li><li>Optionally attach a <strong>receipt</strong> file (images or PDF, up to 5 MB) — counts toward your workspace <a href="/user-guide/storage">Storage</a> quota</li><li>Optionally set an assignee (requires <strong>assign</strong>)</li><li>Save</li></ol><p>Edit from the row menu or the record page while the expense is still <strong>Draft</strong>. After <strong>Submit</strong>, content is locked; use status actions and assignment instead. You can add a receipt while editing a draft expense.</p><h2 id="receipts" tabindex="-1">Receipts <a class="header-anchor" href="#receipts" aria-label="Permalink to &quot;Receipts&quot;">​</a></h2><p>On the expense record page, the <strong>Receipts</strong> section lists uploaded files with a <strong>Download</strong> action. Receipts are stored privately in your workspace Storage quota (not public URLs). Upload failures due to quota or missing Storage entitlement show inline errors on the form.</p><h2 id="status-workflow" tabindex="-1">Status workflow <a class="header-anchor" href="#status-workflow" aria-label="Permalink to &quot;Status workflow&quot;">​</a></h2><p>An expense starts in <strong>Draft</strong>. Move it forward with:</p><ul><li><strong>Submit</strong> (<code>draft → submitted</code>) — sends the expense for approval</li><li><strong>Approve</strong> (<code>submitted → approved</code>) — requires <code>expenses.approve</code>, not limited to the assignee</li><li><strong>Reject</strong> (<code>submitted → rejected</code>) — requires <code>expenses.reject</code>; terminal</li><li><strong>Mark as paid</strong> (<code>approved → paid</code>) — requires <code>expenses.pay</code>; terminal. When <strong>Accounting</strong> is installed, you must choose <strong>Paid from</strong> (cash/bank account); optionally pick an expense P&amp;L account (defaults to Operating Expenses). Accounting posts <strong>Dr</strong> expense / <strong>Cr</strong> paid-from for amount + tax so that bank&#39;s balance decreases</li><li><strong>Cancel</strong> (<code>draft → cancelled</code> or <code>submitted → cancelled</code>) — terminal</li></ul><p>Invalid transitions (e.g. paying directly from Draft) are rejected with a validation error. <code>Rejected</code>, <code>Paid</code>, and <code>Cancelled</code> are terminal — no further transitions.</p><h2 id="optional-vendor-purchase-order-links" tabindex="-1">Optional vendor / purchase order links <a class="header-anchor" href="#optional-vendor-purchase-order-links" aria-label="Permalink to &quot;Optional vendor / purchase order links&quot;">​</a></h2><p>Both links are <strong>soft</strong> — they only appear in the create/edit form when the corresponding module (<strong>Vendors</strong> / <strong>Purchase Orders</strong>) is installed on your workspace, and they&#39;re always optional even when installed. An expense created without either link works exactly the same as one that has them; they&#39;re purely for cross-referencing spend to a supplier or an order.</p><h2 id="assignment" tabindex="-1">Assignment <a class="header-anchor" href="#assignment" aria-label="Permalink to &quot;Assignment&quot;">​</a></h2><p>Users with <strong>assign</strong> can set or clear the assignee from the record page or the create/edit form. The assignee receives an in-app notification when someone else assigns them.</p><h2 id="notes-timeline" tabindex="-1">Notes &amp; timeline <a class="header-anchor" href="#notes-timeline" aria-label="Permalink to &quot;Notes &amp; timeline&quot;">​</a></h2><ul><li><strong>Notes</strong> — free-form notes on the expense</li><li><strong>Timeline</strong> — history of create, update, assignment, status change, note, and delete/restore events</li></ul><h2 id="what-s-not-here-yet" tabindex="-1">What&#39;s not here yet <a class="header-anchor" href="#what-s-not-here-yet" aria-label="Permalink to &quot;What&#39;s not here yet&quot;">​</a></h2><p>Reimbursement/payout tracking beyond the <strong>paid</strong> status, and multi-line (itemized) expenses are planned but not part of this module yet — see the <a href="/getting-started/product-roadmap">Product Roadmap</a>.</p><blockquote><p><strong>Accounting (shipped):</strong> when Accounting is installed, <strong>Mark as paid</strong> posts a journal — see <a href="/user-guide/accounting">Accounting</a>.</p></blockquote>',26)])])}const h=t(r,[["render",n]]);export{g as __pageData,h as default};
